// Spring riverside with cherry blossoms — Canvas 2D direct drawing (repaired data contract)

// ---------- Randomness ----------
function rrange(a, b) { return a + rng() * (b - a); }
function rpick(arr) { return arr[Math.floor(rng() * arr.length)]; }
function finiteOr(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }

// ---------- Value noise / fBm ----------
function makeNoise(seed) {
  const perm = new Uint8Array(512);
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  let s = seed;
  for (let i = 255; i > 0; i--) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const j = s % (i + 1);
    const t = p[i]; p[i] = p[j]; p[j] = t;
  }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  return function(x, y) {
    const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
    const xf = x - Math.floor(x), yf = y - Math.floor(y);
    const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
    const a = perm[perm[X] + Y] / 255;
    const b = perm[perm[X + 1] + Y] / 255;
    const c = perm[perm[X] + Y + 1] / 255;
    const d = perm[perm[X + 1] + Y + 1] / 255;
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  };
}
const noise = makeNoise(777);
function fbm(x, y, oct) {
  let s = 0, a = 0.5, f = 1;
  for (let i = 0; i < oct; i++) {
    s += a * noise(x * f, y * f);
    f *= 2; a *= 0.5;
  }
  return s;
}

// ---------- Sky ----------
function paintSky() {
  const g = ctx.createLinearGradient(0, 0, 0, H * 0.55);
  g.addColorStop(0, '#f8f5ee');
  g.addColorStop(0.5, '#f2ede3');
  g.addColorStop(1, '#eae7db');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H * 0.56);

  const glow = ctx.createRadialGradient(W * 0.68, H * 0.28, 60, W * 0.68, H * 0.28, 640);
  glow.addColorStop(0, 'rgba(255, 251, 242, 0.95)');
  glow.addColorStop(0.5, 'rgba(255, 247, 234, 0.4)');
  glow.addColorStop(1, 'rgba(255, 247, 234, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H * 0.56);

  for (let i = 0; i < 10; i++) {
    const cx = rrange(0, W), cy = rrange(30, H * 0.36);
    const rx = rrange(120, 320), ry = rrange(14, 34);
    const cg = ctx.createRadialGradient(cx, cy, 2, cx, cy, rx);
    cg.addColorStop(0, 'rgba(255,252,248,0.28)');
    cg.addColorStop(1, 'rgba(255,252,248,0)');
    ctx.save();
    ctx.translate(cx, cy); ctx.scale(1, ry / rx); ctx.translate(-cx, -cy);
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.arc(cx, cy, rx, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
}

// ---------- Distant bank ----------
function paintFarBank() {
  const baseY = H * 0.52;
  for (let layer = 0; layer < 4; layer++) {
    const alpha = 0.30 + layer * 0.14;
    const cols = ['#c2d2ba', '#adc5a6', '#9ab98f', '#87ad80'];
    ctx.fillStyle = cols[layer];
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.moveTo(0, H * 0.56);
    for (let x = 0; x <= W; x += 5) {
      const n = fbm(x * 0.006 + layer * 12, layer * 2.5, 4);
      const h = 26 + n * 58 + layer * 5;
      ctx.lineTo(x, baseY - h + layer * 9);
    }
    ctx.lineTo(W, H * 0.56);
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  const hz = ctx.createLinearGradient(0, H * 0.42, 0, H * 0.53);
  hz.addColorStop(0, 'rgba(238,238,224,0)');
  hz.addColorStop(1, 'rgba(226,230,214,0.55)');
  ctx.fillStyle = hz;
  ctx.fillRect(0, H * 0.42, W, H * 0.12);

  for (let i = 0; i < 320; i++) {
    const x = rrange(0, W);
    const yn = fbm(x * 0.006, 2, 3);
    const y = H * 0.52 - (26 + yn * 58) + rrange(-4, 18);
    const r = rrange(1.2, 3.6);
    ctx.fillStyle = rng() < 0.5 ? 'rgba(120,150,110,0.35)' : 'rgba(150,175,135,0.32)';
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
}

// ---------- Distant arched footbridge ----------
function paintBridge() {
  const cx = W * 0.34, cy = H * 0.515;
  const bw = 118, bh = 30;
  ctx.save();
  ctx.globalAlpha = 0.8;
  ctx.strokeStyle = '#b6a894';
  ctx.lineWidth = 4.5;
  ctx.beginPath();
  ctx.moveTo(cx - bw, cy);
  ctx.quadraticCurveTo(cx, cy - bh * 1.9, cx + bw, cy);
  ctx.stroke();
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(cx - bw + 4, cy + 4);
  ctx.quadraticCurveTo(cx, cy - bh * 1.55, cx + bw - 4, cy + 4);
  ctx.stroke();
  ctx.lineWidth = 1.3;
  for (let i = 1; i < 12; i++) {
    const t = i / 12;
    const x = cx - bw + t * bw * 2;
    const ytop = cy - bh * 1.9 * 2 * t * (1 - t);
    ctx.beginPath();
    ctx.moveTo(x, ytop + 0.5);
    ctx.lineTo(x, cy + 4 - (cy + 4 - ytop) * 0.10);
    ctx.stroke();
  }
  ctx.fillStyle = '#b0a290';
  ctx.fillRect(cx - bw - 2, cy - 2, 7, 14);
  ctx.fillRect(cx + bw - 5, cy - 2, 7, 14);
  ctx.restore();
}

// ---------- Water ----------
function paintWater() {
  const top = H * 0.52;
  const g = ctx.createLinearGradient(0, top, 0, H);
  g.addColorStop(0, '#a9c9bc');
  g.addColorStop(0.22, '#7fbcb4');
  g.addColorStop(0.55, '#54aca9');
  g.addColorStop(1, '#3b8c94');
  ctx.fillStyle = g;
  ctx.fillRect(0, top, W, H - top);

  const rg = ctx.createLinearGradient(0, top, 0, top + 46);
  rg.addColorStop(0, 'rgba(206,222,196,0.75)');
  rg.addColorStop(1, 'rgba(206,222,196,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, top, W, 46);

  for (let i = 0; i < 2800; i++) {
    const depth = Math.pow(rng(), 0.7);
    const y = top + 8 + depth * (H - top - 10);
    const persp = 0.25 + depth * 1.0;
    const x = rrange(-40, W + 40);
    const len = rrange(8, 60) * persp;
    const wob = fbm(x * 0.008, y * 0.06, 2);
    const a = 0.05 + (0.18 * (1 - Math.abs(wob - 0.5) * 2)) * (0.4 + depth * 0.7);
    ctx.strokeStyle = rng() < 0.55
      ? `rgba(232,246,240,${a})`
      : `rgba(70,140,142,${a * 0.9})`;
    ctx.lineWidth = 0.7 + depth * 1.5;
    ctx.beginPath();
    ctx.moveTo(x, y + Math.sin(wob * 6.28) * 2);
    ctx.quadraticCurveTo(x + len * 0.5, y - 1.4 * persp, x + len, y);
    ctx.stroke();
  }

  for (let i = 0; i < 300; i++) {
    const depth = rng();
    const y = top + 10 + depth * (H - top - 24);
    const x = rrange(0, W);
    const len = rrange(6, 26) * (0.4 + depth);
    ctx.strokeStyle = `rgba(255,255,248,${0.18 + depth * 0.32})`;
    ctx.lineWidth = 1 + depth * 1.2;
    ctx.beginPath();
    ctx.moveTo(x, y); ctx.lineTo(x + len, y); ctx.stroke();
  }

  const rcx = W * 0.34;
  for (let i = 0; i < 44; i++) {
    const x = rcx + rrange(-118, 118);
    const y = H * 0.525 + rrange(0, 40);
    ctx.strokeStyle = `rgba(178,168,150,${rrange(0.05, 0.20)})`;
    ctx.lineWidth = rrange(1, 2.4);
    ctx.beginPath();
    ctx.moveTo(x + rrange(-6, 6), y);
    ctx.lineTo(x + rrange(-6, 6), y + rrange(2, 9));
    ctx.stroke();
  }
}

// ---------- Cherry blossom (five petals) ----------
function petal(cx, cy, ang, len, wid, col1, col2) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(ang);
  const g = ctx.createLinearGradient(0, 0, Math.max(0.01, len), 0);
  g.addColorStop(0, col1);
  g.addColorStop(0.55, col2);
  g.addColorStop(1, col2);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(len * 0.30, -wid, len * 0.85, -wid * 0.95, len, -wid * 0.18);
  ctx.bezierCurveTo(len * 1.02, 0, len * 0.85, wid * 0.95, 0, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
  ctx.lineWidth = 0.35;
  ctx.beginPath();
  ctx.moveTo(len * 0.15, 0); ctx.lineTo(len * 0.82, -wid * 0.1); ctx.stroke();
  ctx.restore();
}

function blossom(cx, cy, r, tint) {
  if (!isFinite(cx) || !isFinite(cy) || !(r > 0)) return;
  const paletteWhite = { a: 'rgba(255,252,252,0.97)', b: 'rgba(253,236,241,0.9)' };
  const paletteBlush = { a: 'rgba(255,232,236,0.97)', b: 'rgba(248,196,210,0.92)' };
  const paletteRose  = { a: 'rgba(252,206,218,0.96)', b: 'rgba(238,160,182,0.92)' };
  let pal = paletteWhite;
  if (tint < 0.33) pal = paletteWhite;
  else if (tint < 0.70) pal = paletteBlush;
  else pal = paletteRose;

  const rot = rrange(0, Math.PI * 2);
  const len = r * 1.55;
  const wid = r * 0.72;
  const n = 5;
  for (let i = 0; i < n; i++) {
    const a = rot + (i / n) * Math.PI * 2;
    petal(cx, cy, a, len, wid, pal.a, pal.b);
  }
  const cg = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(0.01, r * 0.55));
  cg.addColorStop(0, 'rgba(160,70,95,0.85)');
  cg.addColorStop(1, 'rgba(200,110,135,0)');
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.6, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = 'rgba(190,120,140,0.75)';
  ctx.lineWidth = Math.max(0.35, r * 0.06);
  const stamens = 5 + Math.floor(rng() * 4);
  for (let i = 0; i < stamens; i++) {
    const a = rrange(0, Math.PI * 2);
    const d = r * 0.35;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * d, cy + Math.sin(a) * d);
    ctx.stroke();
    ctx.fillStyle = 'rgba(220,180,120,0.9)';
    ctx.beginPath();
    ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, Math.max(0.3, r * 0.07), 0, Math.PI * 2);
    ctx.fill();
  }
}

// ---------- Cherry branch structure ----------
const twigTips = [];
const twigSupports = [];

function branchSeg(x, y, x2, y2, w1, w2, col) {
  ctx.strokeStyle = col;
  ctx.lineCap = 'round';
  ctx.lineWidth = w2;
  ctx.beginPath();
  ctx.moveTo(x, y);
  const mx = (x + x2) / 2;
  const my = (y + y2) / 2;
  ctx.quadraticCurveTo(mx, my, x2, y2);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(178,148,118,0.30)';
  ctx.lineWidth = Math.max(0.5, w1 * 0.28);
  ctx.beginPath();
  ctx.moveTo(x, y - w1 * 0.24);
  ctx.lineTo(x2, y2 - w1 * 0.24);
  ctx.stroke();
}

// Push helper: guarantees a finite host record with ang and len
function pushHost(hosts, x, y, ang, len) {
  hosts.push({
    x: finiteOr(x, W * 0.7),
    y: finiteOr(y, H * 0.2),
    ang: finiteOr(ang, -Math.PI * 0.5),
    len: finiteOr(len, 6)
  });
}

function branch(x, y, ang, len, wid, depth, isMain) {
  ang = finiteOr(ang, 0);
  len = finiteOr(len, 8);
  const x2 = x + Math.cos(ang) * len;
  const y2 = y + Math.sin(ang) * len;
  const col = depth > 1 ? '#4b3929' : (depth > 0 ? '#5e4635' : '#6f5340');
  branchSeg(x, y, x2, y2, wid, Math.max(0.7, wid * 0.85), col);

  if (depth <= 0 || len < 7) {
    pushHost(twigTips, x2, y2, ang, len);
    return;
  }

  // Along-branch blossom supports: MUST carry finite ang + len too
  if (depth <= 2 && len > 20) {
    const nSup = 1 + Math.floor(rng() * 2);
    for (let i = 0; i < nSup; i++) {
      const t = rrange(0.25, 0.9);
      const px = x + (x2 - x) * t + rrange(-6, 6);
      const py = y + (y2 - y) * t + rrange(-6, 6);
      // support ang points outward from the branch, ang is branch direction
      // plus a small offset; len drives outward blossom spread — give it a
      // modest finite value derived from remaining branch length.
      const supAng = ang + rrange(-0.4, 0.4) + (rng() < 0.5 ? Math.PI * 0.5 : -Math.PI * 0.5);
      const supLen = Math.max(4, len * rrange(0.10, 0.22));
      pushHost(twigSupports, px, py, supAng, supLen);
    }
  }

  const nb = rng() < 0.7 ? 2 : 3;
  const sign0 = rng() < 0.5 ? -1 : 1;
  for (let i = 0; i < nb; i++) {
    const spread = rrange(0.30, 0.75) * (i % 2 === 0 ? sign0 : -sign0);
    const na = ang + spread + rrange(-0.15, 0.15);
    const nl = len * rrange(0.55, 0.78);
    branch(x2, y2, na, nl, Math.max(0.7, wid * 0.66), depth - 1, false);
  }
  if (depth > 0 && rng() < 0.55) {
    pushHost(twigTips, x2, y2, ang, 5);
  }
}

// ---------- Main flowering bough ----------
const mainPath = [];
function buildMainPath() {
  let px = W + 20, py = 30, ang = Math.PI * 0.94;
  const pts = [];
  const segments = 14;
  for (let i = 0; i <= segments; i++) {
    pts.push({ x: px, y: py, ang });
    const stepLen = 42 + rng() * 14;
    ang += rrange(-0.10, 0.10) + (i < 8 ? 0.02 : 0.04);
    px += Math.cos(ang) * stepLen;
    py += Math.sin(ang) * stepLen;
  }
  mainPath.push(...pts);
}

function paintMainBranch() {
  buildMainPath();
  for (let i = 0; i < mainPath.length - 1; i++) {
    const p1 = mainPath[i], p2 = mainPath[i + 1];
    const t = i / (mainPath.length - 1);
    const w = 30 * Math.pow(1 - t, 0.7) + 4;
    ctx.strokeStyle = '#4a3627';
    ctx.lineCap = 'round';
    ctx.lineWidth = w;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.quadraticCurveTo((p1.x + p2.x) / 2, (p1.y + p2.y) / 2, p2.x, p2.y);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(168,138,104,' + (0.30 + 0.2 * (1 - t)) + ')';
    ctx.lineWidth = Math.max(1, w * 0.30);
    ctx.beginPath();
    ctx.moveTo(p1.x - 1, p1.y - w * 0.30);
    ctx.lineTo(p2.x - 1, p2.y - w * 0.30);
    ctx.stroke();
  }
  for (let i = 0; i < 140; i++) {
    const p = mainPath[Math.floor(rrange(0, mainPath.length - 1))];
    if (!p) continue;
    const offX = rrange(-12, 12), offY = rrange(-8, 8);
    const sc = rrange(0.6, 2.2);
    ctx.fillStyle = 'rgba(35,24,17,' + rrange(0.10, 0.28) + ')';
    ctx.beginPath();
    ctx.ellipse(p.x + offX, p.y + offY,
      sc * rrange(1, 2.4), sc * rrange(0.6, 1.2),
      rrange(0, 3), 0, Math.PI * 2);
    ctx.fill();
  }

  for (let i = 1; i < mainPath.length - 1; i += 1) {
    const p = mainPath[i];
    if (rng() < 0.65) {
      const baseAng = p.ang + (rng() < 0.5 ? 1 : -1) * rrange(0.6, 1.3);
      branch(p.x, p.y, baseAng, rrange(60, 110) * (1 - i * 0.04), 5.5, 2, false);
    }
  }
  branch(W * 0.58, 130, -Math.PI * 0.62, 70, 4, 2, false);
  branch(W * 0.72, 100, -Math.PI * 0.55, 60, 4, 2, false);
}

// ---------- Blossoms on twigs ----------
function paintBlossoms() {
  const hosts = twigTips.concat(twigSupports);
  for (const raw of hosts) {
    // Defensive read: every host must have finite x,y,ang,len
    const hx  = finiteOr(raw && raw.x,   W * 0.72);
    const hy  = finiteOr(raw && raw.y,   H * 0.20);
    const hang = finiteOr(raw && raw.ang, -Math.PI * 0.5);
    const hlen = finiteOr(raw && raw.len, 6);

    const den = fbm(hx * 0.008, hy * 0.008, 3);
    const count = 3 + Math.floor(rng() * 6 + den * 6);
    for (let i = 0; i < count; i++) {
      const dist = rrange(0, hlen + 10);
      const a = hang + rrange(-1.3, 1.3);
      const bx = hx + Math.cos(a) * dist + rrange(-6, 6);
      const by = hy + Math.sin(a) * dist + rrange(-6, 6);
      const fall = fbm(bx * 0.012 + 5, by * 0.012 + 3, 2);
      if (fall < 0.32 && rng() < 0.55) continue;
      const depthFactor = Math.min(1, Math.max(0.35,
        1 - Math.hypot(bx - W * 0.75, by - H * 0.18) / (W * 0.55)));
      const r = (rrange(3, 7) + depthFactor * rrange(2, 7)) * rrange(0.85, 1.1);
      if (!(r > 0) || !isFinite(r)) continue;
      blossom(bx, by, r, rng());
    }
  }

  for (let i = 0; i < 26; i++) {
    const x = rrange(W * 0.38, W);
    const y = rrange(0, H * 0.42);
    const r = rrange(3, 8);
    if (isFinite(x) && isFinite(y) && r > 0) blossom(x, y, r, rng());
  }
}

// ---------- Falling petals ----------
const falling = [];
function seedFalling() {
  for (let i = 0; i < 30; i++) {
    falling.push({
      x: rrange(0, W), y: rrange(0, H * 0.7),
      r: rrange(2.2, 4.6), a: rrange(0, Math.PI * 2),
      sp: rrange(0.4, 1.4), drift: rrange(-0.5, 0.5)
    });
  }
}
function paintFalling() {
  for (const p of falling) {
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.a);
    const g = ctx.createLinearGradient(0, 0, Math.max(0.01, p.r), 0);
    g.addColorStop(0, 'rgba(255,250,250,0.95)');
    g.addColorStop(1, 'rgba(250,210,218,0.9)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, p.r, p.r * 0.55, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

// ---------- Main ----------
paintSky();
paintFarBank();
paintBridge();
paintWater();
seedFalling();
paintMainBranch();
paintBlossoms();
paintFalling();

// vignette & final soft light
const vg = ctx.createRadialGradient(W * 0.55, H * 0.42, H * 0.35, W * 0.55, H * 0.42, H * 0.95);
vg.addColorStop(0, 'rgba(0,0,0,0)');
vg.addColorStop(1, 'rgba(30,45,40,0.18)');
ctx.fillStyle = vg;
ctx.fillRect(0, 0, W, H);

const light = ctx.createLinearGradient(W, 0, W * 0.55, H * 0.5);
light.addColorStop(0, 'rgba(255,248,235,0.18)');
light.addColorStop(1, 'rgba(255,248,235,0)');
ctx.fillStyle = light;
ctx.fillRect(0, 0, W, H);
